def utc_now():
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def log(level, message):
    print("%s %s %s" % (utc_now(), level, message), flush=True)
    try:
        CLIENT_LOG_RING.record(level, message)
    except Exception:
        pass  # diagnostics must never break the caller


# Remote diagnostics (owner-approved, 2026-11): a bounded in-memory ring of
# recent WARN/ERROR lines plus every cleanup/replay/lease line, redacted, and
# uploaded periodically. Never written to disk; never contains secrets.
CLIENT_LOG_MAX_LINES = 500
CLIENT_LOG_MAX_BYTES = 256 * 1024
CLIENT_LOG_LINE_MAX = 2048
DIAGNOSTIC_INPUT_MAX = CLIENT_LOG_LINE_MAX
DIAGNOSTIC_MAX_DEPTH = 32
DIAGNOSTIC_TRUNCATED = " [TRUNCATED]"
CLIENT_LOG_UPLOAD_SEC = 300
CLIENT_LOG_LEVELS = ("WARN", "WARNING", "ERROR", "CRITICAL")
CLIENT_LOG_TOPICS = re.compile(r"cleanup|replay|lease|quarantin|V85|stitch", re.IGNORECASE)
# Keep normalization and redaction rules in sync with server_nas_client_logs.go;
# both suites load testdata/nas_diagnostic_redaction.json.
# Scan each name token only from its start. The marker lookahead and the
# consuming token each make one pass; neither can restart inside the token.
_SECRET_MARKER = r"token|secret|passw(?:or)?d|key|signature|credential|authorization|cookie|session|dsn|database_url|x-amz-[a-z0-9_-]+"
_SECRET_NAME = r"(?<![A-Za-z0-9_.-])(?=[A-Za-z0-9_.-]*(?:" + _SECRET_MARKER + r"))[A-Za-z0-9_.-]+"
_SECRET_MARKER_RE = re.compile(_SECRET_MARKER, re.IGNORECASE)
_DIAGNOSTIC_NAME_TOKEN = re.compile(r"[A-Za-z0-9_.-]+")
# A failed escape must consume a whole backslash run only once (Python 3.9+).
_DIAGNOSTIC_ESCAPE = re.compile(r"(?<!\\)\\+(?:u([0-9a-fA-F]{4})|x([0-9a-fA-F]{2})|([nrt]))")
_DIAGNOSTIC_QUOTES = re.compile(r"(?<!\\)\\+([\"'/])")
_DIAGNOSTIC_BYTES = (re.compile(r"\bb'((?:\\.|[^'\\])*)'", re.IGNORECASE),
                     re.compile(r'\bb"((?:\\.|[^"\\])*)"', re.IGNORECASE))
_DIAGNOSTIC_WRAPPER = re.compile(r"\b(?:bytearray|memoryview)\(([^()]*)\)", re.IGNORECASE)


def normalize_diagnostic_text(text):
    # Canonicalize mixed/nested encodings as text, never eval. Bound work and
    # fail closed if an adversarial representation exceeds the decoding budget.
    for _ in range(16):
        decoded = urllib.parse.unquote(html.unescape(text))
        decoded = _DIAGNOSTIC_ESCAPE.sub(
            lambda m: {"n": "\n", "r": "\r", "t": "\t"}[m.group(3)] if m.group(3)
            else chr(int(m.group(1) or m.group(2), 16)), decoded)
        decoded = _DIAGNOSTIC_QUOTES.sub(r"\1", decoded)
        for pattern in _DIAGNOSTIC_BYTES:
            decoded = pattern.sub(r"\1", decoded)
        decoded = _DIAGNOSTIC_WRAPPER.sub(r"\1", decoded)
        if decoded == text:
            return text
        text = decoded
    return "[REDACTED]"


def bounded_diagnostic_text(value):
    """Limit work before decoding/normalization, including native buffers."""
    if isinstance(value, memoryview):
        value = value.cast("B")  # cap bytes, not potentially much larger elements
    if isinstance(value, (bytes, bytearray, memoryview)):
        truncated = len(value) > DIAGNOSTIC_INPUT_MAX
        return bytes(value[:DIAGNOSTIC_INPUT_MAX]).decode("utf-8", "replace"), truncated
    text = str(value)
    return text[:DIAGNOSTIC_INPUT_MAX], len(text) > DIAGNOSTIC_INPUT_MAX


def diagnostic_secret_name(value):
    if not isinstance(value, (str, bytes, bytearray, memoryview)):
        return False
    text, truncated = bounded_diagnostic_text(value)
    if truncated:
        return True  # an omitted suffix may contain a sensitive name
    text = normalize_diagnostic_text(text).casefold()
    return _DIAGNOSTIC_NAME_TOKEN.fullmatch(text) is not None and _SECRET_MARKER_RE.search(text) is not None


_DIAGNOSTIC_URL_QUERY = re.compile(r"\b(?:https?|s3)://|[?#]", re.IGNORECASE)


def redact_diagnostic_url(match):
    # Consume once, including embedded URLs. A fragment ends the current URL
    # candidate; a later nested scheme can still introduce a signed query.
    url = match.group()
    scheme_end = None
    for part in _DIAGNOSTIC_URL_QUERY.finditer(url):
        if part.group() in ("?", "#"):
            if part.group() == "?" and scheme_end is not None and part.start() > scheme_end:
                return url[:part.end()] + "[REDACTED]"
            scheme_end = None
        elif scheme_end is None:
            scheme_end = part.end()
    return url


# Fail closed after a sensitive assignment/pair or standalone auth scheme:
# discard the entire tail, including nested/truncated values and Digest fields.
_REDACTIONS = (
    (re.compile(r"(?is)\b(?:RequestsCookieJar|CookieJar|SimpleCookie|Morsel|Cookie)(?:\s*[:(<]|\s+[A-Za-z0-9_.-]+\s*=)[\s\S]*"), "[REDACTED]"),
    (re.compile(r"(?is)(\bname\s*=\s*[\"'][^\"']*[\"']\s*,\s*value\s*=\s*)[\s\S]*"), r"\1[REDACTED]"),
    (re.compile(r"(?is)([\[(]\s*(?:[\"']\s*)?" + _SECRET_NAME + r"\s*(?:[\"']\s*)?,\s*)[\s\S]*"), r"\1[REDACTED]"),
    (re.compile(r"(?is)(" + _SECRET_NAME + r"[\"']?\s*[=:]\s*)[\s\S]*"), r"\1[REDACTED]"),
    (re.compile(r"(?is)\b(basic|bearer|digest|token|aws4-hmac-sha256)\s+\S[\s\S]*"), r"\1 [REDACTED]"),
    (re.compile(r"(?i)\b(?:postgres(?:ql)?|mysql|redis(?:s)?)://[^\s'\"<>]+"), "[REDACTED]"),
    (re.compile(r"(?i)(?<![a-z0-9+.-])([0-9+.-]*[a-z][a-z0-9+.-]*://)[^/\s'\"<>]*@"), r"\1[REDACTED]@"),
    (re.compile(r"(?i)\b(?:https?|s3)://[^\s'\"<>]+"), redact_diagnostic_url),
    (re.compile(r"\beyJ[A-Za-z0-9_-]+(?:\.[A-Za-z0-9_-]+){0,2}"), "[REDACTED]"),
    (re.compile(r"\btskey-[A-Za-z0-9_-]+"), "[REDACTED]"),
    (re.compile(r"\bAKIA[A-Z0-9]{16}\b"), "[REDACTED]"),
    (re.compile(r"\b100\.(?:6[4-9]|[7-9][0-9]|1[01][0-9]|12[0-7])\.[0-9]{1,3}\.[0-9]{1,3}\b"), "[REDACTED]"),
    (re.compile(r"(?i)\bfd7a:115c:a1e0(?::[0-9a-f]{0,4})+(?:%[A-Za-z0-9_.-]+)?"), "[REDACTED]"),
    (re.compile(r"(?i)(?<![A-Za-z0-9.-])[A-Za-z0-9.-]+\.ts\.net\b"), "[REDACTED]"),
    (re.compile(r"\b(?:sir|sk|rk|pk|ghp|gho|xox[abp])_[A-Za-z0-9_-]{8,}\b"), "[REDACTED]"),
)
_ABSOLUTE_PATH = re.compile(r"(^|[^\w:/.])(/[^\s'\"<>,;)]+)")


def redact_diagnostics(value):
    try:
        return _redact_diagnostics(value)
    except Exception:
        return "[REDACTED]"


def _redact_diagnostics(value, depth=0):
    if depth >= DIAGNOSTIC_MAX_DEPTH:
        return "[REDACTED]"
    if isinstance(value, (str, bytes, bytearray, memoryview)):
        return redact_log_line(value, CLIENT_LOG_RING.output_root, CLIENT_LOG_RING.secrets)
    if isinstance(value, dict):
        return {_redact_diagnostics(k, depth + 1): ("[REDACTED]" if diagnostic_secret_name(k) else _redact_diagnostics(v, depth + 1)) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        if len(value) >= 2 and diagnostic_secret_name(value[0]):
            return [_redact_diagnostics(value[0], depth + 1), "[REDACTED]"]
        return [_redact_diagnostics(v, depth + 1) for v in value]
    return value


def redact_log_line(text, output_root=None, secrets=()):
    """Always fail closed, including conversion and known-secret failures."""
    try:
        return _redact_log_line(text, output_root, secrets)
    except Exception:
        return "[REDACTED]"


def redact_known_diagnostic_secrets(text, variants, truncated):
    for variant in variants:
        text = text.replace(variant, "[REDACTED]")
        if truncated and len(variant) >= 8:
            # A cut can leave only a prefix, possibly spanning whitespace or
            # encodings. Drop the tail from its first eight characters. This
            # deliberately fails closed, without a quadratic suffix search.
            cut = text.find(variant[:8])
            if cut >= 0:
                text = text[:cut] + "[REDACTED]"
    return text


def finish_diagnostic_text(text, truncated, variants):
    if len(text) > CLIENT_LOG_LINE_MAX:
        truncated = True
    if not truncated:
        return text
    text = text[:CLIENT_LOG_LINE_MAX - len(DIAGNOSTIC_TRUNCATED) - len("[REDACTED]")]
    text = redact_known_diagnostic_secrets(text, variants, True)
    # Never retain a token severed by either the input or output cap, including
    # a partial scheme, credential prefix, or incomplete quoted/escaped value.
    tokens = list(re.finditer(r"\s+|\S+", text))
    if tokens and not tokens[-1].group().isspace():
        text = text[:tokens[-1].start()] + "[REDACTED]"
    return text[:CLIENT_LOG_LINE_MAX - len(DIAGNOSTIC_TRUNCATED)] + DIAGNOSTIC_TRUNCATED


def _redact_log_line(text, output_root=None, secrets=()):
    """Remove credentials, signed URLs and absolute host paths from bounded text."""
    text, truncated = bounded_diagnostic_text(text)
    variants = set()
    for secret in secrets:
        variants.update(diagnostic_secret_variants(secret))
    variants = sorted(variants, key=len, reverse=True)
    # Replace before AND after decoding: normalization can alter opaque values.
    text = redact_known_diagnostic_secrets(text, variants, truncated)
    normalized = normalize_diagnostic_text(text)
    normalized_variants = [normalize_diagnostic_text(v) for v in variants]
    if normalized != text and _SECRET_MARKER_RE.search(normalized):
        return finish_diagnostic_text("[REDACTED]", truncated, normalized_variants)
    text = redact_known_diagnostic_secrets(normalized, normalized_variants, truncated)
    for pattern, replacement in _REDACTIONS:
        text = pattern.sub(replacement, text)
    root = str(output_root).rstrip("/") if output_root else None

    def path(match):
        prefix, value = match.group(1), match.group(2)
        if root and (value == root or value.startswith(root + "/")):
            return prefix + "<nas>" + value[len(root):]
        if value.startswith(("/account/", "/api/", "/nas/", "/service/")):
            return prefix + value  # API routes, not host paths
        return prefix + "<path>"
    text = _ABSOLUTE_PATH.sub(path, text)
    return finish_diagnostic_text(text, truncated, variants + normalized_variants)


def diagnostic_secret_variants(value):
    if isinstance(value, (bytes, bytearray, memoryview)):
        value = bytes(value).decode("utf-8", "replace")
    if not isinstance(value, str) or len(value) < 8:
        return ()
    raw = value.encode("utf-8")
    percent = "".join("%%%02X" % b for b in raw)
    return {value, base64.b64encode(raw).decode(), base64.urlsafe_b64encode(raw).decode(),
            base64.b64encode(raw).decode().rstrip("="), base64.urlsafe_b64encode(raw).decode().rstrip("="),
            urllib.parse.quote(value, safe=""), urllib.parse.quote_plus(value), percent, percent.lower(),
            html.escape(value), html.escape(value, quote=False), json.dumps(value)[1:-1],
            "".join("\\u%04x" % ord(c) for c in value), raw.hex(), raw.hex().upper()}


def diagnostic_secret_values(value, sensitive=False, response=False):
    """Collect private values, never their reprs, from config/response fields."""
    if isinstance(value, dict):
        values = []
        for name, item in value.items():
            # Responses include object_key paths: learn credential/cookie fields,
            # while config/env intentionally treat every key-like name as private.
            private = bool(re.search(r"(?i)token|secret|pass|cred|authorization|cookie|session|(?:api|service|pull|access)[_.-]*key", str(name))) if response else (
                diagnostic_secret_name(name) or bool(re.search(r"(?i)pass|cred", str(name))))
            values.extend(diagnostic_secret_values(item, sensitive or private, response))
        return tuple(values)
    if isinstance(value, (list, tuple)):
        return tuple(secret for item in value for secret in diagnostic_secret_values(item, sensitive, response))
    if isinstance(value, (bytes, bytearray, memoryview)):
        value = bytes(value).decode("utf-8", "replace")
    return (value,) if sensitive and isinstance(value, str) and len(value) >= 8 else ()


def client_log_secrets(cfg=None):
    values = diagnostic_secret_values(vars(cfg)) if cfg is not None else ()
    return tuple(set(values + diagnostic_secret_values(dict(os.environ))))


def remember_response_secrets(response):
    """Learn cookie values before response bodies or exceptions can be logged."""
    headers = getattr(response, "headers", None)
    if headers is None or not callable(getattr(headers, "get_all", None)):
        return
    cookie_headers = headers.get_all("Set-Cookie", [])
    if not isinstance(cookie_headers, (list, tuple)):
        return
    values = []
    for header in cookie_headers:
        if not isinstance(header, str):
            continue
        cookies = http.cookies.SimpleCookie()
        try:
            cookies.load(header)
        except http.cookies.CookieError:
            pass
        values.extend(morsel.value for morsel in cookies.values())
        # Retain the raw header as well, including malformed cookie responses.
        values.append(header)
    CLIENT_LOG_RING.add_secrets(values)


class ClientLogRing:
    """Bounded ring of redacted diagnostic lines (count and bytes)."""
    def __init__(self, max_lines=CLIENT_LOG_MAX_LINES, max_bytes=CLIENT_LOG_MAX_BYTES):
        self.lock = threading.Lock()
        self.lines = []
        self.bytes = 0
        self.seq = 0
        self.max_lines, self.max_bytes = max_lines, max_bytes
        self.output_root = None
        self.secrets = client_log_secrets()
        self.error_event = threading.Event()
        self.dropped = 0

    def configure(self, cfg):
        with self.lock:
            self.output_root = getattr(cfg, "output_dir", None)
            self.secrets = tuple(set(self.secrets + client_log_secrets(cfg)))

    def add_secrets(self, values):
        with self.lock:
            self.secrets = tuple(set(self.secrets).union(v for v in values if isinstance(v, str) and len(v) >= 8))

    def record(self, level, message):
        level = str(level).upper()
        if level not in CLIENT_LOG_LEVELS and not CLIENT_LOG_TOPICS.search(str(message)):
            return
        line = redact_log_line(message, self.output_root, self.secrets)
        with self.lock:
            self.seq += 1
            entry = {"seq": self.seq, "at": utc_now_precise(), "level": level, "message": line}
            size = len(line) + 64
            self.lines.append((entry, size))
            self.bytes += size
            while self.lines and (len(self.lines) > self.max_lines or self.bytes > self.max_bytes):
                self.bytes -= self.lines.pop(0)[1]
                self.dropped += 1
        if level in ("ERROR", "CRITICAL"):
            self.error_event.set()

    def since(self, seq):
        with self.lock:
            return [entry for entry, _ in self.lines if entry["seq"] > seq], self.dropped


CLIENT_LOG_RING = ClientLogRing()


def client_log_upload_once(cfg, runtime, inventory, last_seq):
    """Upload the lines recorded after last_seq; returns the new last seq."""
    lines, dropped = CLIENT_LOG_RING.since(last_seq)
    journal = quarantined = None
    if inventory is not None:
        try:
            journal = len(cleanup_journal(inventory))
            quarantined = len(cleanup_quarantined_items(inventory))
        except Exception:
            pass
    body = {"client_version": CLIENT_VERSION, "boot_id": getattr(runtime, "boot_id", ""), "journal_entries": journal,
            "quarantined": quarantined, "dropped_lines": dropped, "lines": lines}
    request_json(cfg, "POST", "/account/connections/client-logs", body=body, timeout=HTTP_TIMEOUT_SEC)
    return lines[-1]["seq"] if lines else last_seq


def client_log_upload_loop(cfg, runtime, inventory, stop_event):
    """Every CLIENT_LOG_UPLOAD_SEC, or right after a new ERROR line."""
    CLIENT_LOG_RING.configure(cfg)
    last_seq = 0
    wait = 60
    last_attempt = None
    while not stop_event.is_set():
        CLIENT_LOG_RING.error_event.wait(wait)
        CLIENT_LOG_RING.error_event.clear()
        if stop_event.is_set():
            return
        if last_attempt is not None and stop_event.wait(max(0, 60 - (time.monotonic() - last_attempt))):
            return
        last_attempt = time.monotonic()
        try:
            last_seq = client_log_upload_once(cfg, runtime, inventory, last_seq)
            wait = CLIENT_LOG_UPLOAD_SEC
        except urllib.error.HTTPError as exc:
            # An API that predates the endpoint: try again in an hour.
            wait = 3600 if exc.code in (400, 404, 405) else CLIENT_LOG_UPLOAD_SEC
        except Exception:
            wait = CLIENT_LOG_UPLOAD_SEC


def env_str(name, default):
    value = os.environ.get(name, "").strip()
    return value or default


def env_int(name, default):
    raw = os.environ.get(name, "").strip()
    if not raw:
        return default
    try:
        return int(raw)
    except ValueError as exc:
        raise SystemExit("%s must be an integer" % name) from exc


def fsync_dir(path):
    fd = os.open(str(path), os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def atomic_write(path, data, mode=0o600):
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(path.name + ".tmp")
    fd = os.open(str(temp), os.O_WRONLY | os.O_CREAT | os.O_TRUNC, mode)
    try:
        with os.fdopen(fd, "wb") as out:
            out.write(data)
            out.flush()
            os.fsync(out.fileno())
        os.replace(str(temp), str(path))
        fsync_dir(path.parent)
    except BaseException:
        try:
            os.unlink(str(temp))
        except FileNotFoundError:
            pass
        raise


def read_json(path, default):
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError:
        return default
    except (OSError, ValueError) as exc:
        raise RuntimeError("invalid state file %s: %s" % (path, exc)) from exc


class Config:
    def __init__(self):
        self.api_base = env_str("STOARAMA_API_BASE", "").rstrip("/")
        self.api_key = env_str("STOARAMA_API_KEY", "")
        self.output_dir = Path(env_str("STOARAMA_OUTPUT_DIR", "/clips"))
        self.state_dir = Path(env_str("STOARAMA_STATE_DIR", "/state"))
        self.progress_file = self.state_dir / "progress.json"
        self.legacy_progress_file = self.state_dir / "cursor.json"
        self.runtime_file = self.state_dir / "runtime.json"
        self.outage_file = self.state_dir / "outage.json"
        self.capacity_file = self.state_dir / "capacity.json"
        self.inventory_file = self.state_dir / "inventory.sqlite3"
        self.current_file = self.state_dir / "stoarama_pull.py"
        self.candidate_file = self.state_dir / "stoarama_pull.candidate.py"
        self.previous_file = self.state_dir / "stoarama_pull.previous.py"
        self.lock_file = self.state_dir / "client.lock"
        self.poll_interval_sec = env_int("STOARAMA_POLL_INTERVAL_SEC", 60)
        self.download_workers = env_int("STOARAMA_DOWNLOAD_WORKERS", DEFAULT_DOWNLOAD_WORKERS)
        self.restore_workers = env_int("STOARAMA_RESTORE_WORKERS", DEFAULT_RESTORE_WORKERS)
        self.inventory_scan_interval_sec = env_int("STOARAMA_INVENTORY_SCAN_INTERVAL_SEC", INVENTORY_SCAN_INTERVAL_SEC)
        # Hash throughput already bounds disk pressure. An additional per-file
        # sleep makes a 100k+ first scan spend hours idle on small clips.
        self.inventory_scan_delay_ms = env_int("STOARAMA_INVENTORY_SCAN_DELAY_MS", 0)
        self.inventory_hash_mbps = env_int("STOARAMA_INVENTORY_HASH_MBPS", 20)
        self.min_free_bytes = env_int("STOARAMA_MIN_FREE_BYTES", DEFAULT_MIN_FREE_BYTES)
        self.update_manifest_url = env_str(
            "STOARAMA_UPDATE_MANIFEST_URL", "https://stoarama.com/nas/download/latest.json"
        )
        self.dry_run = env_str("STOARAMA_DRY_RUN", "0") == "1"
        # Release/deploy safe by default. Operators enable only after migration,
        # API and a completed clean inventory are independently verified.
        self.stitch_enabled = env_str("STOARAMA_V85_STITCH_ENABLED", "false").lower() == "true"
        self.stitch_delete_enabled = env_str("STOARAMA_V85_STITCH_DELETION_ENABLED", "false").lower() == "true"
        self.native_stitch_enabled = env_str("STOARAMA_NATIVE_STITCH_ENABLED", "false").lower() == "true"
        self.is_candidate = env_str("STOARAMA_CANDIDATE", "0") == "1"
        parsed = urllib.parse.urlsplit(self.api_base)
        self.origin = "%s://%s" % (parsed.scheme, parsed.netloc) if parsed.scheme else ""

    def validate(self):
        if not self.api_base or not self.origin:
            raise SystemExit("STOARAMA_API_BASE must be an absolute URL")
        if not self.api_key:
            raise SystemExit("STOARAMA_API_KEY is required")
        if self.poll_interval_sec < 10 or self.poll_interval_sec > 3600:
            raise SystemExit("STOARAMA_POLL_INTERVAL_SEC must be between 10 and 3600")
        if self.download_workers < 1 or self.download_workers > MAX_DOWNLOAD_WORKERS:
            raise SystemExit("STOARAMA_DOWNLOAD_WORKERS must be between 1 and %d" % MAX_DOWNLOAD_WORKERS)
        if self.restore_workers < 1 or self.restore_workers > MAX_RESTORE_WORKERS:
            raise SystemExit("STOARAMA_RESTORE_WORKERS must be between 1 and %d" % MAX_RESTORE_WORKERS)
        if self.inventory_scan_interval_sec < 300 or self.inventory_scan_delay_ms < 0 or self.inventory_hash_mbps < 1 or self.inventory_hash_mbps > 1000:
            raise SystemExit("invalid NAS inventory scan cadence")
        if self.min_free_bytes < 1:
            raise SystemExit("STOARAMA_MIN_FREE_BYTES must be positive")


def boot_id():
    try:
        return Path("/proc/sys/kernel/random/boot_id").read_text(encoding="utf-8").strip()
    except OSError:
        return "unknown"


def cleanup_session_headers(path):
    # Build from the running process on every send, including replay. Never
    # copy an identity out of a journal/checkpoint (replay uses /reconcile).
    if path.startswith("/account/connections/cleanup/"):
        return {"X-Stoarama-Client-Session": boot_id() + " " + CLIENT_VERSION}
    return {}


def request_json(cfg, method, path_or_url, base=None, body=None, timeout=HTTP_TIMEOUT_SEC, authenticate=True):
    base = cfg.api_base if base is None else base
    url = path_or_url if path_or_url.startswith("http") else base + path_or_url
    data = json.dumps(body).encode("utf-8") if body is not None else None
    req = urllib.request.Request(url, method=method, data=data)
    req.add_header("User-Agent", USER_AGENT)
    if authenticate:
        for name, value in cleanup_session_headers(path_or_url).items():
            req.add_header(name, value)
        req.add_header("Authorization", "Bearer " + cfg.api_key)
    if data is not None:
        req.add_header("Content-Type", "application/json")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as response:
            remember_response_secrets(response)
            raw = response.read()
    except urllib.error.HTTPError as exc:
        remember_response_secrets(exc)
        raise
    result = json.loads(raw.decode("utf-8")) if raw else {}
    CLIENT_LOG_RING.add_secrets(diagnostic_secret_values(result, response=True))
    return result


def classify_transport_error(exc):
    reason = exc.reason if isinstance(exc, urllib.error.URLError) else exc
    if isinstance(reason, socket.gaierror):
        return OutageClass.DNS
    if isinstance(reason, (TimeoutError, socket.timeout)):
        return OutageClass.TIMEOUT
    if isinstance(reason, (ConnectionError, ConnectionRefusedError, ConnectionResetError)):
        return OutageClass.CONNECTION
    if isinstance(exc, urllib.error.HTTPError):
        return OutageClass.HTTP
    return OutageClass.OTHER


def transient_error(exc):
    if isinstance(exc, urllib.error.HTTPError):
        return exc.code == 429 or 500 <= exc.code < 600
    return classify_transport_error(exc) in (OutageClass.DNS, OutageClass.TIMEOUT, OutageClass.CONNECTION)


def retry_transient(operation, clip_id, phase):
    for attempt in range(1, DOWNLOAD_ATTEMPTS + 1):
        try:
            return operation(), attempt - 1
        except Exception as exc:
            if not transient_error(exc):
                raise
            if attempt == DOWNLOAD_ATTEMPTS:
                raise RetryExhausted(exc, attempt - 1) from exc
            log(
                "WARN",
                "clip_id=%d %s retry=%d/%d class=%s"
                % (clip_id, phase, attempt, DOWNLOAD_ATTEMPTS - 1, classify_transport_error(exc).value),
            )
            time.sleep(attempt)


def utc_now_precise():
    now_ns = time.time_ns()
    return time.strftime("%Y-%m-%dT%H:%M:%S", time.gmtime(now_ns // 1000000000)) + (".%06dZ" % (now_ns // 1000 % 1000000))


def post_inventory_scan_page(cfg, body, stop_event=None):
    """Keep a scan's walker in place while its durable page is retried."""
    delay = 1
    while True:
        if stop_event is not None and stop_event.is_set():
            return False
        try:
            request_json(cfg, "POST", "/account/connections/inventory", body=body)
            return True
        except urllib.error.HTTPError as exc:
            if stop_event is None or exc.code not in (408, 429, 500, 502, 503, 504):
                raise
            reason = "HTTP %d" % exc.code
        except (urllib.error.URLError, TimeoutError, ConnectionError):
            if stop_event is None:
                raise
            reason = "transport error"
        # The dirty SQLite row and client_updated_at token remain unchanged
        # until an acknowledgement. Replaying an accepted-but-lost response is
        # safe under the server's idempotent upsert; no local row is discarded.
        log("WARN", "inventory upload retry in %ds after %s" % (delay, reason))
        if stop_event.wait(delay):
            return False
        delay = min(delay * 2, 30)


class Inventory:
    """Durable, locally authoritative NAS clip inventory.

    SQLite is intentionally stored on the separate /state mount. Clip writes are
    committed before the server is told it may release a clip. Full scans run in
    the background and use generations so a crash or partial upload can never
    turn an incomplete scan into a mass-missing report.
    """

    def __init__(self, cfg):
        self.cfg = cfg
        self.lock = threading.RLock()
        self.cleanup_claims = {}
        # Execution policy is serialized by the server per plan. Wait here,
        # before opening files or starting the permit clock, including direct
        # callers and already-leased work from an earlier coordinator.
        self.cleanup_execution_lock = threading.Lock()
        # Whole-operation activity fence. Inventory holds this from the first
        # filesystem observation through completion publication; certification
        # only takes it nonblocking at a main-loop delivery-idle boundary.
        self.activity_lock = threading.RLock()
        self.db = sqlite3.connect(str(cfg.inventory_file), timeout=30, check_same_thread=False)
        with self.lock:
            self.db.execute("PRAGMA journal_mode=WAL")
            self.db.execute("PRAGMA synchronous=FULL")
            self.db.execute("PRAGMA foreign_keys=ON")
            self.db.executescript(
                """
                CREATE TABLE IF NOT EXISTS files (
                    clip_id INTEGER PRIMARY KEY,
                    recording_id INTEGER NOT NULL,
                    relative_path TEXT NOT NULL,
                    size_bytes INTEGER NOT NULL,
                    sha256 TEXT NOT NULL,
                    state TEXT NOT NULL,
                    verified_at TEXT,
                    file_mtime_ns INTEGER NOT NULL DEFAULT 0,
                    file_ctime_ns INTEGER NOT NULL DEFAULT 0,
                    file_inode INTEGER NOT NULL DEFAULT 0,
                    file_device INTEGER NOT NULL DEFAULT 0,
                    sidecar_relative_path TEXT NOT NULL DEFAULT '',
                    sidecar_size_bytes INTEGER NOT NULL DEFAULT 0,
                    sidecar_sha256 TEXT NOT NULL DEFAULT '',
                    clip_start_us INTEGER NOT NULL DEFAULT 0,
                    clip_end_us INTEGER NOT NULL DEFAULT 0,
                    seen_generation TEXT NOT NULL DEFAULT '',
                    scan_pass TEXT NOT NULL DEFAULT '',
                    client_updated_at TEXT NOT NULL,
                    dirty INTEGER NOT NULL DEFAULT 1
                );
                CREATE INDEX IF NOT EXISTS files_dirty_clip ON files(dirty, clip_id);
                CREATE INDEX IF NOT EXISTS files_generation ON files(seen_generation);
                CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
                CREATE TABLE IF NOT EXISTS unmatched_files (
                    relative_path TEXT PRIMARY KEY,
                    size_bytes INTEGER NOT NULL,
                    sha256 TEXT NOT NULL,
                    state TEXT NOT NULL,
                    file_mtime_ns INTEGER NOT NULL DEFAULT 0,
                    file_ctime_ns INTEGER NOT NULL DEFAULT 0,
                    file_inode INTEGER NOT NULL DEFAULT 0,
                    file_device INTEGER NOT NULL DEFAULT 0,
                    seen_generation TEXT NOT NULL DEFAULT '',
                    scan_pass TEXT NOT NULL DEFAULT '',
                    client_updated_at TEXT NOT NULL,
                    dirty INTEGER NOT NULL DEFAULT 1
                );
                CREATE INDEX IF NOT EXISTS unmatched_dirty_path ON unmatched_files(dirty,relative_path);
                """
            )
            added_columns = {
                "scan_pass": "TEXT NOT NULL DEFAULT ''",
                "file_ctime_ns": "INTEGER NOT NULL DEFAULT 0",
                "file_inode": "INTEGER NOT NULL DEFAULT 0",
                "file_device": "INTEGER NOT NULL DEFAULT 0",
                "sidecar_relative_path": "TEXT NOT NULL DEFAULT ''",
                "sidecar_size_bytes": "INTEGER NOT NULL DEFAULT 0",
                "sidecar_sha256": "TEXT NOT NULL DEFAULT ''",
                "clip_start_us": "INTEGER NOT NULL DEFAULT 0",
                "clip_end_us": "INTEGER NOT NULL DEFAULT 0",
            }
            for table in ("files", "unmatched_files"):
                columns = {row[1] for row in self.db.execute("PRAGMA table_info(%s)" % table)}
                for column, definition in added_columns.items():
                    if column not in columns:
                        self.db.execute("ALTER TABLE %s ADD COLUMN %s %s" % (table, column, definition))
            self.db.commit()

    def close(self):
        with self.lock:
            self.db.close()

    def _upsert(self, clip, state, verified_at, mtime_ns, generation="live", commit=True, scan_pass="", file_identity=(0, 0, 0), sidecar_evidence=("", 0, "")):
        updated_at = utc_now_precise()
        ctime_ns, inode, device = file_identity
        sidecar_path, sidecar_size, sidecar_sha = sidecar_evidence
        with self.lock:
            self.db.execute(
                """INSERT INTO files
                   (clip_id,recording_id,relative_path,size_bytes,sha256,state,verified_at,file_mtime_ns,file_ctime_ns,file_inode,file_device,sidecar_relative_path,sidecar_size_bytes,sidecar_sha256,clip_start_us,clip_end_us,seen_generation,scan_pass,client_updated_at,dirty)
                   VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1)
                   ON CONFLICT(clip_id) DO UPDATE SET
                     recording_id=excluded.recording_id, relative_path=excluded.relative_path,
                     size_bytes=excluded.size_bytes, sha256=excluded.sha256, state=excluded.state,
                     verified_at=excluded.verified_at, file_mtime_ns=excluded.file_mtime_ns,
                     file_ctime_ns=excluded.file_ctime_ns,file_inode=excluded.file_inode,file_device=excluded.file_device,
                     sidecar_relative_path=excluded.sidecar_relative_path,sidecar_size_bytes=excluded.sidecar_size_bytes,sidecar_sha256=excluded.sidecar_sha256,
                     clip_start_us=excluded.clip_start_us,clip_end_us=excluded.clip_end_us,
                     seen_generation=excluded.seen_generation,scan_pass=excluded.scan_pass,
                     client_updated_at=excluded.client_updated_at,dirty=1""",
                (
                    int(clip["clip_id"]), int(clip["recording_id"]), str(clip["relative_path"]),
                    int(clip["size_bytes"]), str(clip["sha256"]).lower(), state,
                    verified_at, int(mtime_ns), int(ctime_ns), int(inode), int(device),
                    str(sidecar_path), int(sidecar_size), str(sidecar_sha).lower(),
                    optional_certification_timestamp_microseconds(clip.get("clip_start_at"), "clip_start_at"),
                    optional_certification_timestamp_microseconds(clip.get("clip_end_at"), "clip_end_at"),
                    generation, scan_pass, updated_at,
                ),
            )
            if commit:
                self.db.commit()

    def _commit_scan_batch(self, progress=None):
        with self.lock:
            if progress is not None:
                self.db.executemany(
                    "INSERT INTO meta(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                    (("scan_rows_visited", str(progress[0])), ("scan_rows_skipped", str(progress[1])),
                     ("scan_skip_reasons", json.dumps(progress[2], sort_keys=True, separators=(",", ":")))),
                )
            self.db.commit()

    def _publish_scan_batch(self, cfg, generation, started_at, progress, stop_event=None):
        try:
            self._commit_scan_batch(progress)
            self.sync_dirty(cfg, generation, started_at, stop_event=stop_event)
        except Exception as exc:
            raise InventoryProgressError("inventory progress persistence failed") from exc

    def record_verified(self, clip):
        path = self.cfg.output_dir / valid_relative_path(clip)
        stat = path.stat()
        if stat.st_size != int(clip["size_bytes"]):
            raise RuntimeError("inventory size changed after verification for clip %d" % int(clip["clip_id"]))
        self._upsert(clip, "present", utc_now_precise(), stat.st_mtime_ns, file_identity=(stat.st_ctime_ns, stat.st_ino, stat.st_dev))

    def _rows(self, where, params=(), limit=INVENTORY_SYNC_BATCH):
        with self.lock:
            return self.db.execute(
                """SELECT clip_id,recording_id,relative_path,size_bytes,sha256,state,
                          verified_at,file_mtime_ns,client_updated_at,file_ctime_ns,file_inode,file_device,
                          sidecar_relative_path,sidecar_size_bytes,sidecar_sha256
                   FROM files WHERE %s ORDER BY clip_id LIMIT ?""" % where,
                tuple(params) + (limit,),
            ).fetchall()

    @staticmethod
    def _reports(rows):
        reports = []
        for row in rows:
            report = {
                "clip_id": row[0], "recording_id": row[1], "relative_path": row[2],
                "size_bytes": row[3], "sha256": row[4], "state": row[5],
                "verified_at": row[6], "file_mtime_ns": row[7], "client_updated_at": row[8],
            }
            if row[9] > 0 and row[10] > 0 and row[11] > 0 and row[12] and row[13] > 0 and len(row[14]) == 64:
                report.update({
                    "file_ctime_ns": row[9], "file_inode": row[10], "file_device": row[11],
                    "sidecar_relative_path": row[12], "sidecar_size_bytes": row[13], "sidecar_sha256": row[14],
                })
            reports.append(report)
        return reports

    def _mark_clean(self, rows):
        with self.lock:
            self.db.executemany(
                "UPDATE files SET dirty=0 WHERE clip_id=? AND client_updated_at=?",
                [(row[0], row[8]) for row in rows],
            )
            self.db.commit()

    def sync_clip_ids(self, cfg, clip_ids, generation="live"):
        if not clip_ids:
            return
        placeholders = ",".join("?" for _ in clip_ids)
        rows = self._rows("dirty=1 AND clip_id IN (%s)" % placeholders, tuple(clip_ids), len(clip_ids))
        if not rows:
            return
        request_json(cfg, "POST", "/account/connections/inventory", body={
            "generation": generation, "dataset_schema": INVENTORY_DATASET_SCHEMA,
            "root_exclusions": list(INVENTORY_ROOT_EXCLUSIONS), "complete": False, "files": self._reports(rows),
        })
        self._mark_clean(rows)

    def sync_dirty(self, cfg, generation="live", scan_started_at=None, stop_event=None):
        # Establish a full-scan generation even when every local row is already
        # clean (or the NAS contains only excluded roots).
        if generation != "live" and not post_inventory_scan_page(cfg, {
            "generation": generation, "scan_started_at": scan_started_at,
            "dataset_schema": INVENTORY_DATASET_SCHEMA, "root_exclusions": list(INVENTORY_ROOT_EXCLUSIONS),
            "complete": False, "files": [], "unmatched_files": [],
        }, stop_event):
            return
        # Legacy ledgers can retain rows from roots that are outside the v2
        # dataset. Keep the evidence rows, but retire their dirty tokens so they
        # cannot poison every later upload before a scoped full scan starts.
        with self.lock:
            excluded_dirty = self.db.execute(
                """SELECT EXISTS(
                       SELECT 1 FROM files WHERE dirty=1 AND (
                           relative_path='joined' OR relative_path GLOB 'joined/*'
                           OR relative_path='#recycle' OR relative_path GLOB '#recycle/*')
                       UNION ALL
                       SELECT 1 FROM unmatched_files WHERE dirty=1 AND (
                           relative_path='joined' OR relative_path GLOB 'joined/*'
                           OR relative_path='#recycle' OR relative_path GLOB '#recycle/*')
                   )"""
            ).fetchone()[0]
            if excluded_dirty:
                self.db.execute(
                    """UPDATE files SET dirty=0
                       WHERE dirty=1 AND (relative_path='joined' OR relative_path GLOB 'joined/*'
                                          OR relative_path='#recycle' OR relative_path GLOB '#recycle/*')"""
                )
                self.db.execute(
                    """UPDATE unmatched_files SET dirty=0
                       WHERE dirty=1 AND (relative_path='joined' OR relative_path GLOB 'joined/*'
                                          OR relative_path='#recycle' OR relative_path GLOB '#recycle/*')"""
                )
                self.db.commit()
        while True:
            if stop_event is not None and stop_event.is_set():
                return
            rows = self._rows("dirty=1 AND relative_path<>'joined' AND relative_path NOT GLOB 'joined/*' AND relative_path<>'#recycle' AND relative_path NOT GLOB '#recycle/*'")
            if not rows:
                break
            if not post_inventory_scan_page(cfg, {
                "generation": generation, "scan_started_at": scan_started_at,
                "dataset_schema": INVENTORY_DATASET_SCHEMA, "root_exclusions": list(INVENTORY_ROOT_EXCLUSIONS),
                "complete": False, "files": self._reports(rows),
            }, stop_event):
                return
            self._mark_clean(rows)
        while True:
            if stop_event is not None and stop_event.is_set():
                return
            with self.lock:
                rows = self.db.execute(
                    """SELECT relative_path,size_bytes,sha256,state,file_mtime_ns,client_updated_at
                       FROM unmatched_files
                       WHERE dirty=1 AND relative_path<>'joined' AND relative_path NOT GLOB 'joined/*'
                         AND relative_path<>'#recycle' AND relative_path NOT GLOB '#recycle/*'
                       ORDER BY relative_path LIMIT ?""",
                    (INVENTORY_SYNC_BATCH,),
                ).fetchall()
            if not rows:
                return
            reports = [{
                "relative_path": row[0], "size_bytes": row[1], "sha256": row[2],
                "state": row[3], "file_mtime_ns": row[4], "client_updated_at": row[5],
            } for row in rows]
            if not post_inventory_scan_page(cfg, {
                "generation": generation, "scan_started_at": scan_started_at,
                "dataset_schema": INVENTORY_DATASET_SCHEMA, "root_exclusions": list(INVENTORY_ROOT_EXCLUSIONS),
                "complete": False, "files": [], "unmatched_files": reports,
            }, stop_event):
                return
            with self.lock:
                self.db.executemany(
                    "UPDATE unmatched_files SET dirty=0 WHERE relative_path=? AND client_updated_at=?",
                    [(row[0], row[5]) for row in rows],
                )
                self.db.commit()

    def _meta_set(self, values):
        with self.lock:
            self.db.executemany(
                "INSERT INTO meta(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                list(values.items()),
            )
            self.db.commit()

    def _incomplete_scan(self):
        with self.lock:
            values = dict(self.db.execute("SELECT key,value FROM meta").fetchall())
        generation = values.get("generation", "")
        started_at = values.get("scan_started_at", "")
        expected_exclusions = json.dumps(INVENTORY_ROOT_EXCLUSIONS, separators=(",", ":"))
        scope_matches = (
            values.get("dataset_schema") == INVENTORY_DATASET_SCHEMA
            and values.get("root_exclusions") == expected_exclusions
        )
        if generation.startswith("scan-") and started_at and not values.get("scan_completed_at") and scope_matches:
            return generation, started_at
        return None

    def _linked_scan_row_is_current(self, clip, generation, scan_pass, path, sidecar_evidence):
        with self.lock:
            row = self.db.execute(
                """SELECT recording_id,relative_path,size_bytes,sha256,state,file_mtime_ns,seen_generation,
                          file_ctime_ns,file_inode,file_device,sidecar_relative_path,sidecar_size_bytes,sidecar_sha256,
                          clip_start_us,clip_end_us,verified_at
                   FROM files WHERE clip_id=?""",
                (int(clip["clip_id"]),),
            ).fetchone()
            if row is None:
                return False
            different_generation = row[6] != generation
            if different_generation:
                if (row[4] != "present" or not re.fullmatch(r"[0-9a-f]{64}", row[3])
                        or row[13] <= 0 or row[14] <= row[13]):
                    return False
                try:
                    verified = parse_certification_timestamp(row[15], "inventory verified_at")
                except (ValueError, MediaCertificationError):
                    return False
                if verified > datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(minutes=5):
                    return False
            if row[0] != int(clip["recording_id"]) or row[1] != str(clip["relative_path"]):
                return False
            if row[2] != int(clip["size_bytes"]) or row[3] != str(clip["sha256"]).lower():
                return False
            try:
                stat = self._cached_regular_stat(str(clip["relative_path"])) if different_generation else path.stat()
            except FileNotFoundError:
                stat = None
            if stat is None:
                current = row[4] == "missing" and row[5] == 0
            else:
                current = (
                    row[4] in ("present", "mismatch") and row[5] == stat.st_mtime_ns
                    and row[7] != 0 and row[7] == stat.st_ctime_ns
                    and row[8] != 0 and row[8] == stat.st_ino
                    and row[9] != 0 and row[9] == stat.st_dev
                    and stat.st_size == int(clip["size_bytes"])
                    and tuple(row[10:13]) == tuple(sidecar_evidence)
                    and row[13] == optional_certification_timestamp_microseconds(clip.get("clip_start_at"), "clip_start_at")
                    and row[14] == optional_certification_timestamp_microseconds(clip.get("clip_end_at"), "clip_end_at")
                )
            if current:
                if different_generation:
                    # A scope/generation change does not change immutable file
                    # identity. Publish the observation in this generation but
                    # retain the timestamp of the actual payload hash: this is
                    # not a fresh hash or an extension of release eligibility.
                    self.db.execute(
                        "UPDATE files SET seen_generation=?,scan_pass=?,client_updated_at=?,dirty=1 WHERE clip_id=?",
                        (generation, scan_pass, utc_now_precise(), int(clip["clip_id"])),
                    )
                else:
                    self.db.execute("UPDATE files SET scan_pass=? WHERE clip_id=?", (scan_pass, int(clip["clip_id"])))
            return current

    def _cached_regular_stat(self, relative_path):
        parts = Path(relative_path).parts
        if not parts or parts[0] in (JOINED_ROOT,) + INVENTORY_ROOT_EXCLUSIONS or parts[0].endswith("_V85r_keep28"):
            return None
        descriptor = None
        try:
            path, before = confined_regular_file(self.cfg.output_dir, relative_path)
            descriptor = os.open(path, os.O_RDONLY | os.O_NONBLOCK | getattr(os, "O_NOFOLLOW", 0))
            opened = os.fstat(descriptor)
            _, after = confined_regular_file(self.cfg.output_dir, relative_path)
            if (certification_identity(before) == certification_identity(opened)
                    == certification_identity(after)):
                return after
        except (OSError, MediaCertificationError):
            pass
        finally:
            if descriptor is not None:
                os.close(descriptor)
        return None

    def _unmatched_scan_row_is_current(self, relative_path, generation, scan_pass, stat):
        with self.lock:
            row = self.db.execute(
                """SELECT size_bytes,state,file_mtime_ns,seen_generation,file_ctime_ns,file_inode,file_device,sha256
                   FROM unmatched_files WHERE relative_path=?""",
                (relative_path,),
            ).fetchone()
            different_generation = row is not None and row[3] != generation
            if different_generation:
                stat = self._cached_regular_stat(relative_path)
            current = (
                row is not None and stat is not None and row[1] == "present"
                and re.fullmatch(r"[0-9a-f]{64}", row[7]) is not None
                and row[0] == stat.st_size and row[2] == stat.st_mtime_ns
                and row[4] != 0 and row[4] == stat.st_ctime_ns
                and row[5] != 0 and row[5] == stat.st_ino
                and row[6] != 0 and row[6] == stat.st_dev
            )
            if current:
                if different_generation:
                    self.db.execute(
                        "UPDATE unmatched_files SET seen_generation=?,scan_pass=?,client_updated_at=?,dirty=1 WHERE relative_path=?",
                        (generation, scan_pass, utc_now_precise(), relative_path),
                    )
                else:
                    self.db.execute("UPDATE unmatched_files SET scan_pass=? WHERE relative_path=?", (scan_pass, relative_path))
            return current

    def _retire_unmatched_linked_path(self, relative_path, generation, scan_pass):
        with self.lock:
            self.db.execute(
                """UPDATE unmatched_files SET state='missing',seen_generation=?,scan_pass=?,client_updated_at=?,dirty=1
                   WHERE relative_path=? AND state<>'missing'""",
                (generation, scan_pass, utc_now_precise(), relative_path),
            )

    def summary(self):
        with self.lock:
            values = dict(self.db.execute("SELECT key,value FROM meta").fetchall())
        generation = values.get("generation", "")
        if not generation:
            return None
        scan_rows_skipped = int(values.get("scan_rows_skipped", 0))
        skip_reasons = None
        if "scan_skip_reasons" in values:
            try:
                parsed_reasons = json.loads(values["scan_skip_reasons"])
            except (TypeError, ValueError):
                parsed_reasons = None
            if isinstance(parsed_reasons, dict) and all(
                key in INVENTORY_SKIP_REASONS and type(value) is int and value > 0
                for key, value in parsed_reasons.items()
            ) and sum(parsed_reasons.values()) == scan_rows_skipped:
                skip_reasons = parsed_reasons
        summary = {
            "generation": generation,
            "scan_started_at": values.get("scan_started_at") or None,
            "scan_completed_at": values.get("scan_completed_at") or None,
            "scan_pass_started_at": values.get("scan_pass_started_at") or None,
            "scan_rows_visited": int(values.get("scan_rows_visited", 0)),
            "scan_rows_skipped": scan_rows_skipped,
            "clips": int(values.get("clips", 0)),
            "bytes": int(values.get("bytes", 0)),
            "mismatches": int(values.get("mismatches", 0)),
            "unmatched": int(values.get("unmatched", 0)),
            "digest": values.get("digest", ""),
        }
        if skip_reasons is not None:
            summary["scan_skip_reasons"] = skip_reasons
        return summary

    def _digest_and_counts(self):
        digest = hashlib.sha256()
        clips = total_bytes = mismatches = unmatched = 0
        with self.lock:
            rows = self.db.execute(
                "SELECT clip_id,relative_path,size_bytes,sha256,state FROM files WHERE relative_path<>'#recycle' AND relative_path NOT GLOB '#recycle/*' AND relative_path<>'joined' AND relative_path NOT GLOB 'joined/*' ORDER BY clip_id"
            )
            for clip_id, path, size_bytes, sha256, state in rows:
                digest.update(("%d\0%s\0%d\0%s\0%s\n" % (clip_id, path, size_bytes, sha256, state)).encode("utf-8"))
                if state == "present":
                    clips += 1
                    total_bytes += size_bytes
                elif state == "mismatch":
                    mismatches += 1
            for path, size_bytes, sha256, state in self.db.execute(
                "SELECT relative_path,size_bytes,sha256,state FROM unmatched_files WHERE relative_path<>'#recycle' AND relative_path NOT GLOB '#recycle/*' AND relative_path<>'joined' AND relative_path NOT GLOB 'joined/*' ORDER BY relative_path"
            ):
                digest.update(("unmatched\0%s\0%d\0%s\0%s\n" % (path, size_bytes, sha256, state)).encode("utf-8"))
                if state == "present":
                    unmatched += 1
        return digest.hexdigest(), clips, total_bytes, mismatches, unmatched

    def full_scan(self, cfg, stop_event):
        with self.activity_lock:
            return self._full_scan_locked(cfg, stop_event)

    def _full_scan_locked(self, cfg, stop_event):
        resumed = self._incomplete_scan()
        if resumed is None:
            started_at = utc_now_precise()
            generation = "scan-%s-%s" % (time.strftime("%Y%m%dT%H%M%S", time.gmtime()), os.urandom(4).hex())
            self._meta_set({"generation": generation, "scan_started_at": started_at, "scan_completed_at": "", "digest": "",
                            "dataset_schema": INVENTORY_DATASET_SCHEMA,
                            "root_exclusions": json.dumps(INVENTORY_ROOT_EXCLUSIONS, separators=(",", ":"))})
        else:
            generation, started_at = resumed
            log("INFO", "inventory resuming incomplete generation=%s started_at=%s" % (generation, started_at))
        pass_started_at = utc_now_precise()
        scan_pass = os.urandom(8).hex()
        scanned = 0
        skipped = 0
        skip_reasons = {}
        self._meta_set({"scan_pass_started_at": pass_started_at, "scan_rows_visited": "0", "scan_rows_skipped": "0", "scan_skip_reasons": "{}"})

        known_paths = set()
        for sidecar in walk_raw_files(cfg.output_dir):
            if not sidecar.name.endswith(".stoarama.json"):
                continue
            if stop_event.is_set():
                self._commit_scan_batch((scanned, skipped, skip_reasons))
                return
            try:
                sidecar_bytes, _sidecar_stat = stable_regular_file_bytes(sidecar, 1024 * 1024)
                clip = json.loads(sidecar_bytes.decode("utf-8"))
                relative = valid_relative_path(clip)
                if str(relative) != str(clip.get("relative_path", "")):
                    raise ValueError("sidecar path is not canonical")
                path = cfg.output_dir / relative
                if sidecar != stitch_sidecar_path(path):
                    raise ValueError("sidecar location does not match its clip path")
                expected_size = int(clip["size_bytes"])
                expected_sha = str(clip["sha256"]).lower()
                if len(expected_sha) != 64 or any(ch not in "0123456789abcdef" for ch in expected_sha):
                    raise ValueError("sidecar checksum is invalid")
                sidecar_relative = str(sidecar.relative_to(cfg.output_dir))
                sidecar_evidence = (sidecar_relative, len(sidecar_bytes), hashlib.sha256(sidecar_bytes).hexdigest())
                known_paths.add(str(relative))
                self._retire_unmatched_linked_path(str(relative), generation, scan_pass)
                if self._linked_scan_row_is_current(clip, generation, scan_pass, path, sidecar_evidence):
                    scanned += 1
                    if scanned % INVENTORY_SYNC_BATCH == 0:
                        self._publish_scan_batch(
                            cfg, generation, started_at, (scanned, skipped, skip_reasons), stop_event,
                        )
                    continue
                try:
                    stat = path.stat()
                except FileNotFoundError:
                    stat = None
                if stat is not None:
                    try:
                        actual_size, actual_sha, stat = sha256_file_throttled_stable(path, cfg.inventory_hash_mbps, stop_event)
                    except FileNotFoundError:
                        state, verified_at, mtime_ns = "missing", None, 0
                        identity = (0, 0, 0)
                    except FileChangedDuringHash:
                        self._upsert(
                            clip, "mismatch", None, 0, generation, commit=False,
                            scan_pass=scan_pass, file_identity=(0, 0, 0),
                        )
                        raise
                    else:
                        state = "present" if actual_size == expected_size and actual_sha == expected_sha else "mismatch"
                        verified_at = utc_now_precise() if state == "present" else None
                        mtime_ns = stat.st_mtime_ns
                        identity = (stat.st_ctime_ns, stat.st_ino, stat.st_dev)
                else:
                    state, verified_at, mtime_ns = "missing", None, 0
                    identity = (0, 0, 0)
                self._upsert(clip, state, verified_at, mtime_ns, generation, commit=False, scan_pass=scan_pass, file_identity=identity, sidecar_evidence=sidecar_evidence)
                scanned += 1
                if scanned % INVENTORY_SYNC_BATCH == 0:
                    self._publish_scan_batch(
                        cfg, generation, started_at, (scanned, skipped, skip_reasons), stop_event,
                    )
                if cfg.inventory_scan_delay_ms:
                    stop_event.wait(cfg.inventory_scan_delay_ms / 1000.0)
            except InventoryScanStopped:
                self._commit_scan_batch((scanned, skipped, skip_reasons))
                return
            except sqlite3.Error as exc:
                raise InventoryProgressError("inventory state persistence failed") from exc
            except InventoryProgressError:
                raise
            except Exception as exc:
                skipped += 1
                reason = inventory_skip_reason(exc, sidecar=True)
                skip_reasons[reason] = skip_reasons.get(reason, 0) + 1
                log("WARN", f"inventory skipped reason={reason} count={skip_reasons[reason]}")
        for path in walk_raw_files(cfg.output_dir):
            if stop_event.is_set():
                self._commit_scan_batch((scanned, skipped, skip_reasons))
                return
            try:
                if (
                    not path.is_file()
                    or path.name.endswith(".stoarama.json")
                    or re.fullmatch(r".+\.part-\d+", path.name)
                    or re.fullmatch(r"\..+\.invalid-\d+-\d+", path.name)
                ):
                    continue
                relative = str(path.relative_to(cfg.output_dir))
                if relative in known_paths:
                    continue
                stat = path.stat()
                if self._unmatched_scan_row_is_current(relative, generation, scan_pass, stat):
                    scanned += 1
                    if scanned % INVENTORY_SYNC_BATCH == 0:
                        self._publish_scan_batch(
                            cfg, generation, started_at, (scanned, skipped, skip_reasons), stop_event,
                        )
                    continue
                size_bytes, sha256, stat = sha256_file_throttled_stable(path, cfg.inventory_hash_mbps, stop_event)
                updated_at = utc_now_precise()
                with self.lock:
                    self.db.execute(
                        """INSERT INTO unmatched_files(relative_path,size_bytes,sha256,state,file_mtime_ns,file_ctime_ns,file_inode,file_device,seen_generation,scan_pass,client_updated_at,dirty)
                           VALUES(?,?,?,'present',?,?,?,?,?,?,?,1)
                           ON CONFLICT(relative_path) DO UPDATE SET size_bytes=excluded.size_bytes,sha256=excluded.sha256,
                             state='present',file_mtime_ns=excluded.file_mtime_ns,file_ctime_ns=excluded.file_ctime_ns,
                             file_inode=excluded.file_inode,file_device=excluded.file_device,
                             seen_generation=excluded.seen_generation,scan_pass=excluded.scan_pass,
                             client_updated_at=excluded.client_updated_at,dirty=1""",
                        (relative, size_bytes, sha256, stat.st_mtime_ns, stat.st_ctime_ns, stat.st_ino, stat.st_dev, generation, scan_pass, updated_at),
                    )
                scanned += 1
                if scanned % INVENTORY_SYNC_BATCH == 0:
                    self._publish_scan_batch(
                        cfg, generation, started_at, (scanned, skipped, skip_reasons), stop_event,
                    )
                if cfg.inventory_scan_delay_ms:
                    stop_event.wait(cfg.inventory_scan_delay_ms / 1000.0)
            except InventoryScanStopped:
                self._commit_scan_batch((scanned, skipped, skip_reasons))
                return
            except sqlite3.Error as exc:
                raise InventoryProgressError("inventory state persistence failed") from exc
            except InventoryProgressError:
                raise
            except Exception as exc:
                skipped += 1
                reason = inventory_skip_reason(exc, sidecar=False)
                skip_reasons[reason] = skip_reasons.get(reason, 0) + 1
                log("WARN", f"inventory skipped reason={reason} count={skip_reasons[reason]}")
        # Flush and publish every successfully observed row, but never promote a
        # partial generation. In particular, do not turn unseen prior rows into
        # "missing" when an unreadable/corrupt path was skipped.
        self._commit_scan_batch((scanned, skipped, skip_reasons))
        self.sync_dirty(cfg, generation, started_at, stop_event=stop_event)
        if stop_event.is_set():
            return
        if skipped:
            raise RuntimeError("inventory scan incomplete: %d path(s) could not be verified" % skipped)
        completed_at = utc_now_precise()
        with self.lock:
            self.db.execute(
                """UPDATE files SET state='missing',verified_at=NULL,seen_generation=?,scan_pass=?,dirty=1,client_updated_at=?
                   WHERE state<>'missing' AND scan_pass<>? AND (seen_generation=? OR client_updated_at<=?)
                     AND relative_path<>'#recycle' AND relative_path NOT GLOB '#recycle/*' AND relative_path<>'joined' AND relative_path NOT GLOB 'joined/*'""",
                (generation, scan_pass, completed_at, scan_pass, generation, pass_started_at),
            )
            self.db.execute(
                """UPDATE unmatched_files SET state='missing',seen_generation=?,scan_pass=?,dirty=1,client_updated_at=?
                   WHERE state<>'missing' AND scan_pass<>? AND (seen_generation=? OR client_updated_at<=?)
                     AND relative_path<>'#recycle' AND relative_path NOT GLOB '#recycle/*' AND relative_path<>'joined' AND relative_path NOT GLOB 'joined/*'""",
                (generation, scan_pass, completed_at, scan_pass, generation, pass_started_at),
            )
            self.db.commit()
        self.sync_dirty(cfg, generation, started_at, stop_event=stop_event)
        if stop_event.is_set():
            return
        digest, clips, total_bytes, mismatches, unmatched = self._digest_and_counts()
        if stop_event.is_set():
            return
        if not post_inventory_scan_page(cfg, {
            "generation": generation, "scan_started_at": started_at,
            "dataset_schema": INVENTORY_DATASET_SCHEMA, "root_exclusions": list(INVENTORY_ROOT_EXCLUSIONS),
            "scan_completed_at": completed_at, "digest": digest, "complete": True, "files": [],
        }, stop_event):
            return
        self._meta_set({
            "generation": generation, "scan_started_at": started_at,
            "scan_completed_at": completed_at, "digest": digest,
            "clips": str(clips), "bytes": str(total_bytes), "mismatches": str(mismatches),
            "unmatched": str(unmatched),
        })
        log("INFO", "inventory scan complete generation=%s clips=%d bytes=%d mismatches=%d unmatched=%d" % (generation, clips, total_bytes, mismatches, unmatched))


def inventory_loop(cfg, inventory, stop_event):
    # Let the main drain establish connectivity first; inventory is deliberately
    # background work and never blocks incoming clip delivery.
    if stop_event.wait(10):
        return
    while not stop_event.is_set():
        try:
            with inventory.activity_lock:
                inventory.sync_dirty(cfg, stop_event=stop_event)
                if stop_event.is_set():
                    return
                inventory.full_scan(cfg, stop_event)
        except Exception as exc:
            log("WARN", "inventory scan/sync failed: %s" % exc)
        stop_event.wait(cfg.inventory_scan_interval_sec)


class Runtime:
    def __init__(self, cfg, inventory=None):
        self.stitch_enabled = getattr(cfg, "stitch_enabled", False)
        progress = read_json(cfg.progress_file, {})
        if not progress and cfg.legacy_progress_file.exists():
            progress = read_json(cfg.legacy_progress_file, {})
        self.lock = threading.Lock()
        self.joined_completion_lock = threading.Lock()
        self.joined_work_condition = threading.Condition()
        self.joined_work_credit = 0
        self.cursor_id = max(0, int(progress.get("after_id", 0)))
        self.clips_pulled = max(0, int(progress.get("clips_pulled", 0)))
        self.bytes_pulled = max(0, int(progress.get("bytes_pulled", 0)))
        self.phase = Phase.STARTING
        self.last_success_at = progress.get("last_success_at")
        self.last_error = ""
        self.last_error_at = None
        self.started_at = utc_now()
        self.boot_id = boot_id()
        self.previous_exit = self._previous_exit(cfg)
        self.heartbeat_succeeded = False
        self.list_succeeded = False
        self.stable_marked = False
        self.release_candidate_at_start = bool(getattr(cfg, "is_candidate", False))
        self.inventory = inventory
        # Remote authorization is process-local and fail-closed. A restart must
        # negotiate again; no manifest, environment, or progress file enables it.
        self.joined_protocol_version = 0
        self.joined_protocol_generation = 0
        self.joined_delivery = None
        self.joined_transfer = None
        self.joined_raw_priority_polled_at = 0.0
        self.joined_raw_priority_pending = False
        # A new client explicitly clears any stale server-side capacity until
        # the independent probe proves that the configured NAS mount is live.
        self.storage = {"available": False}
        self.storage_observed_monotonic = time.monotonic()
        # Restarts always re-enter the blocked side of hysteresis. A fresh high
        # watermark stat must explicitly reopen admission, so a failed state
        # write can never resurrect an older durable "unblocked" decision.
        self.capacity_blocked = True
        self.capacity_reserved_bytes = 0
        self.batch = {
            "completed_at": None,
            "clips": 0,
            "bytes": 0,
            "duration_ms": 0,
            "workers": cfg.download_workers,
            "retries": 0,
            "failures": 0,
        }

    def _previous_exit(self, cfg):
        prior = read_json(cfg.runtime_file, {})
        status = prior.get("exit")
        if status == PreviousExit.CLEAN.value:
            return PreviousExit.CLEAN
        if status == PreviousExit.SELF_UPDATE.value:
            return PreviousExit.SELF_UPDATE
        if not prior:
            return PreviousExit.UNKNOWN
        if prior.get("boot_id") == self.boot_id:
            return PreviousExit.UNCLEAN_PROCESS
        return PreviousExit.UNCLEAN_REBOOT

    def set_phase(self, phase):
        with self.lock:
            self.phase = phase

    def set_error(self, message):
        with self.lock:
            self.last_error = str(message)[:1000]
            self.last_error_at = utc_now()
            self.phase = Phase.DEGRADED

    def add_successes(self, cfg, cursor_id, successes):
        with self.lock:
            advanced = cursor_id > self.cursor_id
            self.cursor_id = max(self.cursor_id, cursor_id)
            self.clips_pulled += len(successes)
            self.bytes_pulled += sum(item[1] for item in successes)
            self.last_success_at = utc_now()
            self.last_error = ""
            self.last_error_at = None
            snapshot = self.progress_payload()
        if not cfg.dry_run:
            atomic_write(cfg.progress_file, json.dumps(snapshot, separators=(",", ":")).encode("utf-8"))
            if advanced:
                self.grant_joined_work_credit()

    def progress_payload(self):
        return {
            "after_id": self.cursor_id,
            "clips_pulled": self.clips_pulled,
            "bytes_pulled": self.bytes_pulled,
            "last_success_at": self.last_success_at,
        }

    def set_batch(self, clips, downloaded_bytes, duration_sec, retries, failures):
        duration_ms = max(1, round(duration_sec * 1000))
        with self.lock:
            self.batch = {
                "completed_at": utc_now(),
                "clips": clips,
                "bytes": downloaded_bytes,
                "duration_ms": duration_ms,
                "workers": self.batch["workers"],
                "retries": retries,
                "failures": failures,
            }

    def set_storage(self, storage):
        with self.lock:
            self.storage = storage.copy()
            self.storage_observed_monotonic = time.monotonic()

    def is_capacity_blocked(self):
        with self.lock:
            return self.capacity_blocked

    def joined_protocol_enabled(self):
        with self.lock:
            return self.joined_protocol_version == JOINED_PROTOCOL_VERSION

    def joined_background_enabled(self):
        with self.lock:
            return (
                self.joined_protocol_version == JOINED_PROTOCOL_VERSION
                and self.joined_protocol_generation >= JOINED_BACKGROUND_MIN_GENERATION
            )

    def joined_fair_share_enabled(self):
        with self.lock:
            return (
                self.joined_protocol_version == JOINED_PROTOCOL_VERSION
                and self.joined_protocol_generation >= JOINED_FAIR_SHARE_MIN_GENERATION
            )

    def grant_joined_work_credit(self):
        with self.joined_work_condition:
            self.joined_work_credit = 1
            self.joined_work_condition.notify()

    def consume_joined_work_credit(self):
        with self.joined_work_condition:
            if not self.joined_work_credit:
                return False
            self.joined_work_credit = 0
            return True

    def wait_joined_work_credit(self, timeout):
        with self.joined_work_condition:
            if not self.joined_work_credit:
                self.joined_work_condition.wait(timeout)
            if not self.joined_work_credit:
                return False
            self.joined_work_credit = 0
            return True

    def apply_joined_protocol_response(self, response):
        version = response.get("joined_protocol_version") if isinstance(response, dict) else None
        generation = response.get("joined_protocol_generation") if isinstance(response, dict) else None
        valid = (
            isinstance(response, dict) and set(response) == {
                "ok", "joined_delivery_accepted", "joined_protocol_version", "joined_protocol_generation",
            }
            and response.get("ok") is True and type(response.get("joined_delivery_accepted")) is bool
            and type(version) is int and version in (0, JOINED_PROTOCOL_VERSION)
            and type(generation) is int and 0 <= generation <= 0x7fffffffffffffff
            and (generation > 0 or version == 0)
            and (response.get("joined_delivery_accepted") is True or (version == 0 and generation == 0))
        )
        with self.joined_completion_lock:
            with self.lock:
                if not valid or generation < self.joined_protocol_generation:
                    self.joined_protocol_version = 0
                    return
                if generation == self.joined_protocol_generation:
                    if version != self.joined_protocol_version:
                        self.joined_protocol_version = 0
                    return
                self.joined_protocol_generation = generation
                self.joined_protocol_version = version
                self.joined_transfer = None
        with self.joined_work_condition:
            self.joined_work_condition.notify_all()

    def run_joined_completion(self, operation):
        # Completion is serialized with heartbeat response application. Once
        # admitted, the operation finishes; HTTP operations remain bounded by
        # HTTP_TIMEOUT_SEC. The next joined boundary observes any downgrade.
        with self.joined_completion_lock:
            with self.lock:
                if self.joined_protocol_version != JOINED_PROTOCOL_VERSION:
                    return False
            operation()
            return True

    def set_joined_delivery_error(self, artifact_id, blocker, retry_sec):
        attempted = datetime.datetime.now(datetime.timezone.utc)
        retry = attempted + datetime.timedelta(seconds=retry_sec)
        with self.lock:
            self.joined_delivery = {
                "artifact_id": artifact_id,
                "blocker": blocker,
                "attempted_at": attempted.isoformat().replace("+00:00", "Z"),
                "retry_at": retry.isoformat().replace("+00:00", "Z"),
            }

    def clear_joined_delivery_error(self):
        with self.lock:
            self.joined_delivery = None

    def set_joined_transfer(self, artifact_id, offset_bytes, operation):
        with self.lock:
            if self.joined_protocol_version != JOINED_PROTOCOL_VERSION:
                return
            self.joined_transfer = {
                "artifact_id": int(artifact_id),
                "protocol_generation": self.joined_protocol_generation,
                "offset_bytes": max(0, int(offset_bytes)),
                "operation": operation,
                "errno_class": "",
                "observed_at": utc_now_precise(),
            }

    def set_joined_transfer_error(self, artifact_id, exc):
        with self.lock:
            if self.joined_transfer is None or self.joined_transfer["artifact_id"] != int(artifact_id):
                return
            self.joined_transfer["errno_class"] = joined_errno_class(exc)
            self.joined_transfer["observed_at"] = utc_now_precise()

    def clear_joined_transfer(self):
        with self.lock:
            self.joined_transfer = None

    def reserve_joined_storage(self, cfg, storage, expected_bytes):
        """Reserve one joined range only when it cannot consume raw headroom."""
        available = bool(storage.get("available"))
        free_bytes = int(storage.get("free_bytes", 0)) if available else 0
        expected_bytes = max(0, int(expected_bytes))
        with self.lock:
            usable_free = free_bytes - self.capacity_reserved_bytes - expected_bytes
            threshold = (
                cfg.min_free_bytes + JOINED_RAW_HEADROOM_BYTES
                + (CAPACITY_RESUME_HYSTERESIS_BYTES if self.capacity_blocked else 0)
            )
            if not available or usable_free < threshold:
                return False
            self.capacity_reserved_bytes += expected_bytes
            return True

    def reserve_storage(self, cfg, storage, expected_bytes=0):
        """Atomically admit expected bytes and persist hysteresis across restarts."""
        available = bool(storage.get("available"))
        free_bytes = int(storage.get("free_bytes", 0)) if available else 0
        expected_bytes = max(0, int(expected_bytes))
        with self.lock:
            was_blocked = self.capacity_blocked
            resume_at = cfg.min_free_bytes + CAPACITY_RESUME_HYSTERESIS_BYTES
            usable_free = free_bytes - self.capacity_reserved_bytes - expected_bytes
            self.capacity_blocked = (not available) or usable_free < (resume_at if was_blocked else cfg.min_free_bytes)
            changed = self.capacity_blocked != was_blocked
            if not self.capacity_blocked:
                self.capacity_reserved_bytes += expected_bytes
            if changed and self.capacity_blocked:
                try:
                    atomic_write(cfg.capacity_file, b'{"blocked":true}')
                except Exception:
                    self.capacity_blocked = True
                    raise
        return not self.capacity_blocked

    def release_storage_reservation(self, expected_bytes):
        with self.lock:
            self.capacity_reserved_bytes = max(0, self.capacity_reserved_bytes - max(0, int(expected_bytes)))

    def upload_probe_activity(self):
        with self.lock:
            return self.phase.value, self.bytes_pulled, self.joined_transfer is not None

    def heartbeat_payload(self, outage):
        with self.lock:
            payload = {
                "cursor_id": self.cursor_id,
                "clips_pulled": self.clips_pulled,
                "bytes_pulled": self.bytes_pulled,
                "client_version": CLIENT_VERSION,
                "client_started_at": self.started_at,
                "client_boot_id": self.boot_id,
                "client_phase": self.phase.value,
                "client_previous_exit": self.previous_exit.value,
                "client_last_success_at": self.last_success_at,
                "client_last_error": self.last_error,
                "client_last_error_at": self.last_error_at,
                "last_batch": self.batch.copy(),
                "capacity_blocked": self.capacity_blocked,
                "joined_protocol_version": self.joined_protocol_version,
            }
            release = {"candidate": self.release_candidate_at_start and not self.stable_marked,
                       "stable": self.stable_marked}
            storage = self.storage.copy() if self.storage is not None else None
            storage_age = time.monotonic() - self.storage_observed_monotonic
            joined_delivery = self.joined_delivery.copy() if self.joined_delivery is not None else None
            joined_transfer = self.joined_transfer.copy() if self.joined_transfer is not None else None
        if outage:
            payload["last_outage"] = outage
        if storage is not None and storage_age <= STORAGE_TELEMETRY_MAX_AGE_SEC:
            payload["storage"] = storage
        elif self.storage is not None:
            payload["storage"] = {"available": False}
        if joined_delivery is not None and payload["joined_protocol_version"] == JOINED_PROTOCOL_VERSION:
            payload["joined_delivery"] = joined_delivery
        if joined_transfer is not None and payload["joined_protocol_version"] == JOINED_PROTOCOL_VERSION:
            payload["joined_transfer"] = joined_transfer
        if self.inventory is not None:
            inventory = self.inventory.summary()
            if inventory is not None:
                payload["inventory"] = inventory
        cleanup, cleanup_error, cleanup_error_at = CLEANUP_STATUS.snapshot()
        if self.inventory is not None:
            cleanup.update(cleanup_quarantine_status(self.inventory))
        if cleanup:
            payload["cleanup"] = redact_diagnostics(cleanup)
        if cleanup_error and not payload["client_last_error"]:
            payload["client_last_error"], payload["client_last_error_at"] = cleanup_error, cleanup_error_at
        if getattr(self, "stitch_enabled", False):
            stitch, error, at = STITCH_STATUS.snapshot()
            payload["stitch"] = redact_diagnostics(dict(stitch, last_error=error, last_error_at=at))
        payload["client_last_error"] = redact_diagnostics(payload["client_last_error"])
        host_facts = getattr(self, "host_facts", None)
        if host_facts is not None:
            try:
                facts = host_facts()
                payload["host"] = dict(facts, release=release) if isinstance(facts, dict) else facts
            except Exception as exc:
                log("WARN", "host facts unavailable: %s" % exc)
        return payload


def mark_runtime(cfg, runtime, exit_status="running"):
    atomic_write(
        cfg.runtime_file,
        json.dumps({"boot_id": runtime.boot_id, "started_at": runtime.started_at, "exit": exit_status}).encode("utf-8"),
    )


def check_storage(cfg):
    for path in (cfg.output_dir, cfg.state_dir):
        if not path.exists() or not path.is_dir():
            raise RuntimeError("required storage directory is missing: %s" % path)
        if not os.path.ismount(str(path)):
            raise RuntimeError("required storage directory is not mounted: %s" % path)
        probe = path / (".stoarama-write-check-%d" % os.getpid())
        atomic_write(probe, b"ok")
        probe.unlink()
        fsync_dir(path)
    if cfg.output_dir.resolve() == cfg.state_dir.resolve():
        raise RuntimeError("clip and state mounts must be different")


def storage_status(cfg):
    """Read capacity from a stable mounted-directory descriptor, never its host fallback."""
    fd = None
    try:
        fd = os.open(cfg.output_dir, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
        opened = os.fstat(fd)
        if not os.path.ismount(str(cfg.output_dir)):
            return {"available": False}
        current = os.stat(cfg.output_dir)
        if (opened.st_dev, opened.st_ino) != (current.st_dev, current.st_ino):
            return {"available": False}
        usage = os.fstatvfs(fd)
        unit = usage.f_frsize or usage.f_bsize
        return {
            "available": True,
            "total_bytes": usage.f_blocks * unit,
            "free_bytes": usage.f_bavail * unit,
        }
    except OSError:
        return {"available": False}
    finally:
        if fd is not None:
            os.close(fd)


def storage_probe_loop(cfg, runtime, stop_event):
    """Keep filesystem syscalls off the liveness-critical heartbeat thread."""
    while not stop_event.is_set():
        try:
            runtime.set_storage(storage_status(cfg))
        except Exception as exc:
            runtime.set_storage({"available": False})
            log("WARN", "storage telemetry probe failed: %s" % exc)
        stop_event.wait(HEARTBEAT_INTERVAL_SEC)


def require_storage_capacity(cfg, runtime, expected_bytes=0):
    """Use a fresh mount-bound stat for every admission decision."""
    try:
        storage = storage_status(cfg)
    except Exception:
        storage = {"available": False}
    runtime.set_storage(storage)
    if not runtime.reserve_storage(cfg, storage, expected_bytes):
        if storage.get("available"):
            detail = "NAS free-space reserve reached"
        else:
            detail = "NAS free-space check unavailable"
        runtime.set_phase(Phase.BLOCKED)
        raise RuntimeError(detail)


def require_joined_storage_capacity(cfg, runtime, expected_bytes):
    """Fail joined admission without changing raw capacity or process phase."""
    try:
        storage = storage_status(cfg)
    except Exception:
        storage = {"available": False}
    runtime.set_storage(storage)
    if not runtime.reserve_joined_storage(cfg, storage, expected_bytes):
        raise JoinedDownloadYield("joined storage yielded to raw reserve")


# Exact-file NAS cleanup. A backend dry-run decision never reaches unlink.
class CleanupInterrupted(RuntimeError):
    """Cancellation is not evidence of a file conflict."""


class NASMediaFence:
    """Allow concurrent delivery, then fence app writers for deletions only.

    App writers and cleanup deletions exclude each other. Several cleanup
    workers may hold the fence together: each deletes only its own exact,
    separately permitted file, and same-folder namespace changes made by them
    are accounted for exactly (see CleanupDirectoryLog). A waiting writer
    blocks new cleanup holders so delivery is never starved."""
    def __init__(self):
        self.condition = threading.Condition()
        self.writers = 0
        self.writers_waiting = 0
        self.cleaners = 0

    @property
    def exclusive(self):
        return self.cleaners > 0

    def delivery(self, fn):
        def wrapped(*args, **kwargs):
            with self.condition:
                self.writers_waiting += 1
                try:
                    while self.cleaners:
                        self.condition.wait(1)
                finally:
                    self.writers_waiting -= 1
                self.writers += 1
            try:
                return fn(*args, **kwargs)
            finally:
                with self.condition:
                    self.writers -= 1
                    self.condition.notify_all()
        return wrapped

    def acquire_cleanup(self, stop_event, deadline):
        with self.condition:
            while self.writers or self.writers_waiting:
                if stop_event.is_set() or time.monotonic() >= deadline:
                    raise CleanupInterrupted("cleanup writer fence timed out or cancelled")
                self.condition.wait(0.2)
            self.cleaners += 1

    def release_cleanup(self):
        with self.condition:
            self.cleaners -= 1
            self.condition.notify_all()


NAS_MEDIA_FENCE = NASMediaFence()


class CleanupDirectoryLog:
    """Per-directory record of the names this process itself unlinked.

    A cleanup file proves its parent's exact namespace and must find it
    unchanged right before its own unlink. With several workers in one folder,
    the only acceptable difference is exactly the set of names other workers
    of this process unlinked meanwhile, each under its own permit and ledger
    line. Listings and unlinks in one directory are serialized by its lock, so
    every listing is consistent with the log. Any other change (a new, changed
    or foreign-removed name) still fails closed."""
    def __init__(self):
        self.lock = threading.Lock()
        self.dirs = {}

    def enter(self, key):
        with self.lock:
            state = self.dirs.get(key)
            if state is None:
                state = self.dirs[key] = {"lock": threading.Lock(), "seq": 0, "removed": [], "users": 0}
            state["users"] += 1
            return state

    def leave(self, key):
        with self.lock:
            state = self.dirs.get(key)
            if state is not None:
                state["users"] -= 1
                if state["users"] <= 0:
                    del self.dirs[key]


CLEANUP_DIRECTORIES = CleanupDirectoryLog()


def cleanup_namespace_sha256(names):
    return hashlib.sha256(cleanup_json_bytes({"namespace_version": 2, "names": sorted(names)})).hexdigest()


def cleanup_identity(info):
    return [info.st_size, info.st_mtime_ns, info.st_ctime_ns, info.st_ino, info.st_dev]


def cleanup_json_bytes(payload):
    return json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")


def cleanup_journal(inventory, item_id=None, phase=None, body=None, owner=None):
    with inventory.lock:
        inventory.db.execute("CREATE TABLE IF NOT EXISTS cleanup_receipts(item_id INTEGER PRIMARY KEY,phase TEXT NOT NULL,body TEXT NOT NULL)")
        try:
            if item_id is not None:
                claim = inventory.cleanup_claims.get(item_id)
                if claim is not None or owner is not None:
                    if claim is None or claim[0] is not owner:
                        raise RuntimeError("cleanup journal is reserved")
                    current = inventory.db.execute("SELECT phase,body FROM cleanup_receipts WHERE item_id=?", (item_id,)).fetchone()
                    cleanup_quarantine_tables(inventory)
                    quarantined = inventory.db.execute("SELECT 1 FROM cleanup_quarantine WHERE item_id=?", (item_id,)).fetchone()
                    if current != claim[1] or quarantined:
                        raise RuntimeError("cleanup journal changed; deferred without modifying evidence")
                # Observation permits hash the submitted proof bytes. Preserve
                # insertion order so replay sends the same proof serialization;
                # sorting a journal would change its binding after a lost reply.
                next_row = None if phase is None else (phase, json.dumps(body, ensure_ascii=False)
                                                       if phase == "observe" else cleanup_json_bytes(body).decode())
                if owner is not None:
                    # Compare-and-swap in SQL too: even an independent SQLite
                    # writer cannot be overwritten between the check and write.
                    expected = claim[1]
                    if expected is None:
                        if next_row is not None:
                            inventory.db.execute("INSERT INTO cleanup_receipts VALUES(?,?,?)", (item_id, *next_row))
                    elif next_row is None:
                        changed = inventory.db.execute("DELETE FROM cleanup_receipts WHERE item_id=? AND phase=? AND body=?", (item_id, *expected))
                        if changed.rowcount != 1:
                            raise RuntimeError("cleanup journal changed; deferred")
                    else:
                        changed = inventory.db.execute("UPDATE cleanup_receipts SET phase=?,body=? WHERE item_id=? AND phase=? AND body=?", (*next_row, item_id, *expected))
                        if changed.rowcount != 1:
                            raise RuntimeError("cleanup journal changed; deferred")
                elif next_row is None:
                    inventory.db.execute("DELETE FROM cleanup_receipts WHERE item_id=?", (item_id,))
                else:
                    inventory.db.execute("INSERT INTO cleanup_receipts VALUES(?,?,?) ON CONFLICT(item_id) DO UPDATE SET phase=excluded.phase,body=excluded.body", (item_id, *next_row))
            inventory.db.commit()
            if item_id is not None and owner is not None:
                inventory.cleanup_claims[item_id] = (owner, next_row)
        except Exception:
            inventory.db.rollback()
            raise
        return inventory.db.execute("SELECT item_id,phase,body FROM cleanup_receipts ORDER BY item_id").fetchall()


def cleanup_blocked_items(inventory):
    # Release holds this same lock across the quarantine -> journal transaction.
    with inventory.lock:
        cleanup_journal(inventory)
        cleanup_quarantine_tables(inventory)
        rows = inventory.db.execute("SELECT item_id FROM cleanup_receipts UNION SELECT item_id FROM cleanup_quarantine").fetchall()
        inventory.db.commit()
        return {row[0] for row in rows} | set(inventory.cleanup_claims)


def cleanup_reserve_item(inventory, item_id):
    with inventory.lock:
        if item_id in cleanup_blocked_items(inventory):
            CLEANUP_STATUS.add("skipped_blocked_items")
            log("WARN", "cleanup item=%d journal unresolved; left unprocessed" % item_id)
            return None
        owner = object()
        inventory.cleanup_claims[item_id] = (owner, None)
        return owner


class CleanupFile:
    """Directory-FD traversal; no symlinks, hardlinks or nested filesystems."""
    def __init__(self, cfg, item, stop_event, deadline):
        self.cfg, self.item, self.stop_event, self.deadline = cfg, item, stop_event, deadline
        self.fds = []
        self.files = []
        self.ancestors = []
        self.root_identity = None
        self.stage_timings = {}
        self.permit_started = None
        self.permit_expiry = None
        self.unlink_attempted = False
        self.media_unlinked = False
        self.sidecar_unlinked = False
        self.directory_key = None
        self.directory = None
        self.proof_names = None
        self.proof_seq = None
        # MD5 of the media bytes, computed in the same read as their SHA-256.
        # It is not part of the proof; protocol-2 servers use it to match the
        # R2 single-part ETag instead of downloading the recovery copy.
        self.media_md5 = None

    def check_active(self):
        if self.stop_event.is_set():
            raise CleanupInterrupted("cleanup stopped")
        if self.permit_started is not None and time.monotonic() - self.permit_started >= CLEANUP_PERMIT_MAX_AGE_SEC:
            raise CleanupPermitRefused("deadline_exceeded", "cleanup observation deadline exceeded before next unlink")
        if self.permit_expiry is not None and self.permit_expiry <= datetime.datetime.now(datetime.timezone.utc):
            raise CleanupPermitRefused("permit_expired", "cleanup deletion permit expired before next unlink")
        if time.monotonic() >= self.deadline:
            raise CleanupInterrupted("cleanup lease or permit deadline exceeded")

    def __enter__(self):
        try:
            self.check_active()
            raw = self.item["relative_path"]
            if (not isinstance(raw, str) or not raw or len(raw.encode()) > 1024 or raw.startswith(("/", "#", "@"))
                    or any(p in ("", ".", "..") for p in raw.split("/")) or any(c in raw for c in ("\\", "\0", "\r", "\n"))):
                raise RuntimeError("unsafe cleanup path")
            if not os.path.ismount(str(self.cfg.output_dir)):
                raise RuntimeError("cleanup NAS root is not mounted")
            root = os.open(str(self.cfg.output_dir), os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
            self.fds.append(root)
            info = os.fstat(root)
            self.root_identity = [info.st_dev, info.st_ino]
            for part in raw.split("/")[:-1]:
                fd = os.open(part, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=self.fds[-1])
                self.fds.append(fd)
                info = os.fstat(fd)
                if info.st_dev != self.root_identity[0]:
                    raise RuntimeError("cleanup nested filesystem excluded")
                self.ancestors.append([info.st_dev, info.st_ino])
            self.name = raw.split("/")[-1]
            parent = os.fstat(self.fds[-1])
            self.directory_key = (parent.st_dev, parent.st_ino)
            self.directory = CLEANUP_DIRECTORIES.enter(self.directory_key)
            self.open_file(self.name, self.item["frozen_identity"])
            if self.item["sidecar_required"]:
                self.open_file(self.name + ".stoarama.json", self.item["frozen_sidecar_identity"])
            return self
        except BaseException:
            self.__exit__(None, None, None)
            raise

    def open_file(self, name, frozen):
        fd = os.open(name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=self.fds[-1])
        self.files.append((name, fd, frozen))
        info = os.fstat(fd)
        if (not stat_module.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_dev != self.root_identity[0]
                or cleanup_identity(info) != frozen):
            raise RuntimeError("cleanup file differs from exact audited identity")

    def list_parent(self):
        started = time.monotonic()
        before = os.fstat(self.fds[-1])
        entries = []
        # Entry names define the namespace. Unlisted sibling contents are never
        # deletion authority. Target/sidecar hash and identity checks stay exact.
        for name in os.listdir(self.fds[-1]):
            self.check_active()
            entries.append(os.fsencode(name).hex())
        after = os.fstat(self.fds[-1])
        if cleanup_identity(before) != cleanup_identity(after):
            raise RuntimeError("cleanup directory changed during enumeration")
        self.stage_timings["namespace_ms"] = self.stage_timings.get("namespace_ms", 0) + (time.monotonic() - started) * 1000
        return entries

    def parent_snapshot(self):
        """(names, seq): a listing consistent with this process's unlink log."""
        if self.directory is None:
            return self.list_parent(), 0
        with self.directory["lock"]:
            return self.list_parent(), self.directory["seq"]

    def own_unlinks_since(self, seq):
        if self.directory is None:
            return set()
        # removed[k] carries seq k+1 (seq only grows, by one per unlink).
        return {name for _, name in self.directory["removed"][seq:]}

    def namespace_unchanged(self, names, seq, current):
        """True when current differs from names only by this process's own
        exact unlinks after seq (the caller holds the directory lock or
        passes a listing taken under it)."""
        return set(current) == set(names) - self.own_unlinks_since(seq) and len(current) == len(set(current))

    def parent_members(self):
        return cleanup_namespace_sha256(self.parent_snapshot()[0])

    def check_paths(self, skip_media=False):
        self.check_active()
        root = os.lstat(self.cfg.output_dir)
        if not os.path.ismount(str(self.cfg.output_dir)) or [root.st_dev, root.st_ino] != self.root_identity:
            raise RuntimeError("cleanup NAS mount changed")
        parts = self.item["relative_path"].split("/")[:-1]
        for n, part in enumerate(parts):
            info = os.stat(part, dir_fd=self.fds[n], follow_symlinks=False)
            opened = os.fstat(self.fds[n+1])
            if not stat_module.S_ISDIR(info.st_mode) or [info.st_dev, info.st_ino] != self.ancestors[n] or [opened.st_dev, opened.st_ino] != self.ancestors[n]:
                raise RuntimeError("cleanup ancestor changed")
        for name, fd, frozen in (self.files[1:] if skip_media else self.files):
            current = os.stat(name, dir_fd=self.fds[-1], follow_symlinks=False)
            opened = os.fstat(fd)
            if (not stat_module.S_ISREG(current.st_mode) or current.st_nlink != 1 or opened.st_nlink != 1
                    or cleanup_identity(current) != frozen or cleanup_identity(opened) != frozen):
                raise RuntimeError("cleanup file identity changed")

    def proof(self):
        started = time.monotonic()
        before_names, before_seq = self.parent_snapshot()
        before_members = cleanup_namespace_sha256(before_names)
        hash_started = time.monotonic()
        hashes = []
        sidecar_bytes = b""
        for n, (_, fd, _) in enumerate(self.files):
            os.lseek(fd, 0, os.SEEK_SET)
            digest = hashlib.sha256()
            md5 = hashlib.md5() if n == 0 else None
            while True:
                self.check_active()
                block = os.read(fd, 1024 * 1024)
                if not block:
                    break
                digest.update(block)
                if md5 is not None:
                    md5.update(block)
                if n:
                    sidecar_bytes += block
                    if len(sidecar_bytes) > 1024 * 1024:
                        raise RuntimeError("cleanup sidecar exceeds bound")
            hashes.append(digest.hexdigest())
            if md5 is not None:
                self.media_md5 = md5.hexdigest()
        self.stage_timings["hash_ms"] = (time.monotonic() - hash_started) * 1000
        self.check_paths()
        after_names, _ = self.parent_snapshot()
        if hashes[0] != self.item["sha256"] or not self.namespace_unchanged(before_names, before_seq, after_names):
            raise RuntimeError("cleanup content or directory changed")
        self.proof_names, self.proof_seq = before_names, before_seq
        proof = {"root": self.root_identity, "ancestors": self.ancestors, "identity": self.item["frozen_identity"],
                 "sha256": hashes[0], "parent_members_sha256": before_members}
        if self.item["sidecar_required"]:
            sidecar = json.loads(sidecar_bytes)
            binding = {"clip_id": self.item["source_id"], "recording_id": self.item["recording_id"],
                       "relative_path": self.item["relative_path"], "size_bytes": self.item["size_bytes"], "sha256": self.item["sha256"]}
            if type(sidecar.get("schema_version")) is not int or sidecar["schema_version"] not in (1, 2) or any(type(sidecar.get(k)) is not type(v) or sidecar[k] != v for k, v in binding.items()):
                raise RuntimeError("cleanup sidecar does not bind exact source identity")
            for field in ("clip_start_at", "clip_end_at"):
                actual = parse_certification_timestamp(sidecar.get(field), field)
                expected = parse_certification_timestamp(self.item["start_at" if field == "clip_start_at" else "end_at"], field)
                if actual != expected:
                    raise RuntimeError("cleanup sidecar registered interval differs from catalog")
                binding[field] = expected.isoformat()
            proof["sidecar"] = {"identity": self.item["frozen_sidecar_identity"], "sha256": hashes[1], "binding": binding}
        self.stage_timings["proof_ms"] = (time.monotonic() - started) * 1000
        return proof

    def record_unlink(self, name):
        if self.directory is not None:
            self.directory["seq"] += 1
            self.directory["removed"].append((self.directory["seq"], os.fsencode(name).hex()))

    def delete_exact(self, proof):
        # Only reached after a short-lived, exact backend permit and app writer
        # fence. Directories and every unlisted entry are left intact.
        self.check_paths()
        exact = (self.proof_names is not None and self.directory is not None
                 and cleanup_namespace_sha256(self.proof_names) == proof["parent_members_sha256"])
        lock = self.directory["lock"] if self.directory is not None else threading.Lock()
        # The final listing, checks and unlinks are one step for this folder:
        # no other worker of this process can list or unlink in between.
        with lock:
            current = self.list_parent()
            if exact:
                unchanged = self.namespace_unchanged(self.proof_names, self.proof_seq, current)
            else:
                unchanged = cleanup_namespace_sha256(current) == proof["parent_members_sha256"]
            if not unchanged:
                raise RuntimeError("cleanup folder membership changed before unlink")
            self.check_paths()
            self.check_active()
            self.unlink_attempted = True
            os.unlink(self.name, dir_fd=self.fds[-1])
            self.media_unlinked = True
            self.record_unlink(self.name)
            if self.item["sidecar_required"]:
                self.check_paths(skip_media=True)
                self.check_active()
                os.unlink(self.files[1][0], dir_fd=self.fds[-1])
                self.sidecar_unlinked = True
                self.record_unlink(self.files[1][0])
        os.fsync(self.fds[-1])

    def __exit__(self, *_args):
        for _, fd, _ in reversed(self.files):
            os.close(fd)
        for fd in reversed(self.fds):
            os.close(fd)
        self.files, self.fds = [], []
        if self.directory_key is not None:
            CLEANUP_DIRECTORIES.leave(self.directory_key)
            self.directory_key = self.directory = None


# Independent client-side deletion guard (safety council, 2026-11). Defence in
# depth: it never trusts the server. Before every unlink the client itself maps
# the file's top-level NAS folder to a stream (pinned map; unknown -> refuse),
# reads the clip interval from the physical sidecar binding (raw) or the
# output's bounds cross-checked against the dated collated path (collated;
# unknown -> refuse), and refuses when the interval overlaps that stream's
# pinned keep28 window or the server's stream_id disagrees. It also enforces
# hard local 24h caps and writes an append-only, fsynced deletion ledger. A
# client whose pinned files fail their SHA check refuses every deletion and
# keeps doing all non-delete work. Refusal never unlinks; it is reported to the
# server as a non-delete outcome (conflict observation or unverified receipt).
#
# CLEANUP_KEEP28_POLICY is backend/internal/api/nas_cleanup_keep28_policy.json
# byte-for-byte (zlib+base64; the tests compare them). CLEANUP_FOLDER_STREAMS
# is clients/nas-pull/nas_cleanup_folder_streams.json byte-for-byte, derived
# read-only from production: every NAS folder prefix seen in
# nas_inventory_files.relative_path, recording_collation_outputs.nas_relative_path
# and recording_clips.display_path (account 47) that maps to exactly one stream;
# the prefix is the first path component, or "recordings/<id>" for that layout.
